s=s[:i]+r'''const REQUIRED_COLUMNS = ["date", "employee", "category", "amount", "currency", "receipt"] as const;
type Column = (typeof REQUIRED_COLUMNS)[number];

/** Splits one CSV line into fields; quoted fields may contain commas and "" for a quote. */
function parseFields(line: string): string[] {
  const fields: string[] = [];
  let i = 0;
  for (;;) {
    let value = "";
    while (i < line.length && (line[i] === " " || line[i] === "\t")) i++;
    if (line[i] === '"') {
      i++;
      for (;;) {
        if (i >= line.length) break;
        if (line[i] === '"') {
          if (line[i + 1] === '"') {
            value += '"';
            i += 2;
          } else {
            i++;
            break;
          }
        } else {
          value += line[i++];
        }
      }
      // Tolerate stray characters between the closing quote and the next comma.
      while (i < line.length && line[i] !== ",") value += line[i++];
    } else {
      while (i < line.length && line[i] !== ",") value += line[i++];
    }
    fields.push(value.trim());
    if (i >= line.length) return fields;
    i++; // skip the comma
  }
}

function isValidDate(value: string): boolean {
  const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(value);
  if (!match) return false;
  const year = Number(match[1]);
  const month = Number(match[2]);
  const day = Number(match[3]);
  if (month < 1 || month > 12 || day < 1) return false;
  const leap = (year % 4 === 0 && year % 100 !== 0) || year % 400 === 0;
  const daysInMonth = [31, leap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31][month - 1];
  return day <= daysInMonth;
}

/** Parses an amount like "12", "12.5" or "12.50" into integer cents, or null if invalid. */
function parseAmountCents(value: string): bigint | null {
  const match = /^(\d+)(?:\.(\d{1,2}))?$/.exec(value);
  if (!match) return null;
  const cents = BigInt(match[1]) * 100n + BigInt((match[2] ?? "").padEnd(2, "0"));
  return cents > 0n ? cents : null;
}

/** Represents a number exactly as numerator / 10^scale, based on its shortest decimal form. */
function toDecimal(rate: number): { numerator: bigint; scale: number } {
  const match = /^(-?)(\d+)(?:\.(\d+))?(?:e([+-]?\d+))?$/i.exec(String(rate));
  if (!match) throw new ExpenseFileError(`Invalid exchange rate: ${rate}`);
  const fraction = match[3] ?? "";
  let numerator = BigInt(match[2] + fraction);
  let scale = fraction.length - Number(match[4] ?? 0);
  if (scale < 0) {
    numerator *= 10n ** BigInt(-scale);
    scale = 0;
  }
  return { numerator: match[1] ? -numerator : numerator, scale };
}

/** Multiplies cents by the rate and rounds to the nearest cent, halves up. */
function convertCents(amountCents: bigint, rate: number): number {
  const { numerator, scale } = toDecimal(rate);
  const denominator = 10n ** BigInt(scale);
  const product = amountCents * numerator;
  const rounded = (2n * product + denominator) / (2n * denominator);
  // BigInt division truncates towards zero; correct for negative products.
  const floor = 2n * product + denominator < 0n && (2n * product + denominator) % (2n * denominator) !== 0n
    ? rounded - 1n
    : rounded;
  return Number(floor);
}

export function reviewExpenses(csv: string, policy: Policy, fxRates: FxRates): ExpenseReport {
  const physicalLines = csv.split("\n").map((line) => (line.endsWith("\r") ? line.slice(0, -1) : line));

  let headerIndex = -1;
  let columnIndex: Record<Column, number> | null = null;
  let headerLength = 0;
  const lines: ReviewedLine[] = [];
  const rejected: RejectedLine[] = [];
  const seen = new Set<string>();
  const dailyTotals = new Map<string, number>();
  const totals = new Map<string, { approvedCents: number; flaggedCents: number }>();

  for (let index = 0; index < physicalLines.length; index++) {
    const raw = physicalLines[index];
    if (raw.trim() === "") continue;
    const lineNumber = index + 1;

    if (headerIndex < 0) {
      headerIndex = index;
      const names = parseFields(raw).map((name) => name.trim().toLowerCase());
      headerLength = names.length;
      const found = {} as Record<Column, number>;
      for (const column of REQUIRED_COLUMNS) {
        const position = names.indexOf(column);
        if (position < 0) throw new ExpenseFileError(`Missing column: ${column}`);
        found[column] = position;
      }
      columnIndex = found;
      continue;
    }

    const columns = columnIndex!;
    const fields = parseFields(raw);
    const reject = (reason: string) => rejected.push({ line: lineNumber, reason });

    if (fields.length !== headerLength) {
      reject("wrong number of fields");
      continue;
    }
    const date = fields[columns.date];
    const employee = fields[columns.employee];
    const category = fields[columns.category];
    const amount = fields[columns.amount];
    const currency = fields[columns.currency];
    const receipt = fields[columns.receipt].toLowerCase();

    if (!isValidDate(date)) {
      reject("invalid date");
      continue;
    }
    if (employee === "") {
      reject("missing employee");
      continue;
    }
    if (!Object.hasOwn(policy.categories, category)) {
      reject("unknown category");
      continue;
    }
    const amountCents = parseAmountCents(amount);
    if (amountCents === null) {
      reject("invalid amount");
      continue;
    }
    if (currency !== "CHF" && !Object.hasOwn(fxRates, currency)) {
      reject("unknown currency");
      continue;
    }
    if (receipt !== "yes" && receipt !== "no") {
      reject("invalid receipt flag");
      continue;
    }

    const rate = currency === "CHF" ? 1 : fxRates[currency];
    const amountChfCents = convertCents(amountCents, rate);
    const categoryPolicy = policy.categories[category];
    const violations: Violation[] = [];

    const duplicateKey = JSON.stringify([employee, date, category, amountCents.toString(), currency]);
    if (seen.has(duplicateKey)) violations.push("DUPLICATE");
    seen.add(duplicateKey);

    if (categoryPolicy.perItemLimitCents !== undefined && amountChfCents > categoryPolicy.perItemLimitCents) {
      violations.push("OVER_ITEM_LIMIT");
    }

    const dailyKey = JSON.stringify([employee, date, category]);
    const dailyTotal = (dailyTotals.get(dailyKey) ?? 0) + amountChfCents;
    dailyTotals.set(dailyKey, dailyTotal);
    if (categoryPolicy.dailyLimitCents !== undefined && dailyTotal > categoryPolicy.dailyLimitCents) {
      violations.push("OVER_DAILY_LIMIT");
    }

    if (receipt === "no" && amountChfCents > policy.receiptRequiredAboveCents) {
      violations.push("NO_RECEIPT");
    }

    lines.push({ line: lineNumber, date, employee, category, amountChfCents, violations });

    const employeeTotals = totals.get(employee) ?? { approvedCents: 0, flaggedCents: 0 };
    if (violations.length === 0) employeeTotals.approvedCents += amountChfCents;
    else employeeTotals.flaggedCents += amountChfCents;
    totals.set(employee, employeeTotals);
  }

  if (headerIndex < 0) throw new ExpenseFileError("Missing header");

  return { lines, rejected, totals: Object.fromEntries(totals) };
}
'''
open(p,'w').write(s)
